{"path": "tests/Feature/Situations/EveryBareSiblingWalledSituationTest.php", "content": "<?php

use Modules\AI\Domain\Decision\DefenseNeedEvaluator;
use Modules\AI\Tests\Support\Situation;
use OGame\Factories\PlanetServiceFactory;
use OGame\Models\Planet;
use Tests\IsolatedAccountTestCase;

require_once __DIR__ . '/../../Support/Situation.php';

uses(IsolatedAccountTestCase::class);

// QUAL-003 (invariant:NAKED_BESIDE_WALLED, aspect:shipyard): the invariant counts the account, and a
// login has to reach every planet that stands at zero beside a sibling that holds a wall. A pass that
// served one sibling per login needed as many logins as the account has planets -- more than its own
// day of sessions -- so the cohort read still found three planets at zero beside one holding 1,312
// units. The story below plants two bare siblings behind one walled planet and reads them after a
// single login, at the bound (two bare) rather than at the easy middle (one).

test('one login gives every bare sibling the wall the account already holds elsewhere', function (): void {
    $situation = Situation::of($this)
        ->resources(50_000_000, 50_000_000, 50_000_000)
        ->defence('rocket_launcher', 20)
        ->colony()
        ->colony()
        ->levelEveryPlanet('robot_factory', 2)
        ->levelEveryPlanet('shipyard', 4)
        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000)
        ->session();

    $naked = [];
    foreach (Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)->pluck('id') as $planetId) {
        $planet = app(PlanetServiceFactory::class)->make((int) $planetId, true);
        if (app(DefenseNeedEvaluator::class)->standingUnits($planet) === 0) {
            $naked[] = $planetId;
        }
    }

    // A short build may already be complete by the time the session's own clock has advanced to every
    // intent, so the wall counts whether it is standing or still paid for in the yard.
    expect($naked)->toBe([], 'these planets stayed at zero defence after one login; ' . $situation->account());
});

// The bound on the other side: one login does not stack a wall on the sibling that already holds one.
// The walled planet is planted at the behaviour file's ceiling, where nothing further is wanted, so a
// wall ordered there would show up as more than the planted count.
test('a login adds nothing to the walled planet while the sibling is bare', function (): void {
    $situation = Situation::of($this)
        ->resources(50_000_000, 50_000_000, 50_000_000)
        ->defence('rocket_launcher', 20_000)
        ->colony()
        ->levelEveryPlanet('robot_factory', 2)
        ->levelEveryPlanet('shipyard', 4)
        ->stockEveryPlanet(50_000_000, 50_000_000, 50_000_000)
        ->session();

    $home = app(PlanetServiceFactory::class)->make($this->currentPlanetId, true);
    $colonyId = (int) Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
        ->whereKeyNot($this->currentPlanetId)->value('id');
    $colony = app(PlanetServiceFactory::class)->make($colonyId, true);

    expect(app(DefenseNeedEvaluator::class)->standingUnits($colony))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account())
        ->and(app(DefenseNeedEvaluator::class)->standingUnits($home))->toBe(20_000, 'expected the walled planet untouched; ' . $situation->account());
});
"}
